import random
import string
from typing import List

# Data type: whitespace-separated QNames
# Each token is either "local" or "prefix:local". ASCII whitespace separates tokens.
# We generate realistic sets that could reference attribute sets in XSLT.

PREFIXES = [
    "x", "ex", "p", "q", "ns", "html", "xsl", "my", "data", "cfg",
]
LOCALS = [
    "attrs", "common", "base", "header", "footer", "title", "meta", "all",
    "link", "bold", "italic", "emph", "code", "warn", "ok", "error",
    "a", "b", "c", "main", "nav", "content", "style", "wide", "narrow",
]

WHITESPACE_CHOICES = [" ", "\t", "\n", "\r", "  ", "\t ", " \n"]

def _rand_local(r: random.Random) -> str:
    # XML Name production (simplified): start with letter or underscore, then letters, digits, hyphen, underscore, dot
    start_chars = string.ascii_letters + "_"
    other_chars = start_chars + string.digits + "-."
    if r.random() < 0.7:
        base = r.choice(LOCALS)
    else:
        base = r.choice(start_chars)
        base += ''.join(r.choice(other_chars) for _ in range(r.randint(0, 8)))
    return base

def _rand_prefix(r: random.Random) -> str:
    if r.random() < 0.7:
        return r.choice(PREFIXES)
    # Occasionally synthesize a random valid prefix
    start_chars = string.ascii_letters + "_"
    other_chars = start_chars + string.digits + "-."
    s = r.choice(start_chars)
    s += ''.join(r.choice(other_chars) for _ in range(r.randint(0, 6)))
    return s

def _rand_qname(r: random.Random) -> str:
    if r.random() < 0.5:
        return _rand_local(r)
    else:
        return f"{_rand_prefix(r)}:{_rand_local(r)}"

def _make_attrset_list(r: random.Random) -> str:
    # Choose between 1 and ~10 tokens, sometimes repeated or mixed with varying whitespace.
    n = 1 if r.random() < 0.2 else r.randint(2, 10)
    tokens: List[str] = []
    for _ in range(n):
        tokens.append(_rand_qname(r))
        # Occasionally include duplicates to trigger merge/precedence logic
        if r.random() < 0.15:
            tokens.append(tokens[-1])
    # Interleave with assorted whitespace
    parts: List[str] = []
    for i, t in enumerate(tokens):
        if i > 0:
            parts.append(r.choice(WHITESPACE_CHOICES))
        parts.append(t)
    s = ''.join(parts)
    # Randomly add leading/trailing whitespace (the stub trims leading spaces loosely)
    if r.random() < 0.5:
        s = r.choice(WHITESPACE_CHOICES) + s
    if r.random() < 0.5:
        s = s + r.choice(WHITESPACE_CHOICES)
    # Ensure size constraint for the stub (<=256). If longer, trim but keep non-space
    if len(s) > 256:
        s = s[:256].rstrip()
        if not s.strip():
            # ensure at least one token
            s = _rand_qname(r)
    return s

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Produce one interesting whitespace-separated QName list
    payload = _make_attrset_list(r)
    # Return as bytes (UTF-8)
    return payload.encode('utf-8')

import os
import random
import string
from typing import List

# Generator for valid URI strings used by libxslt loaders and security checks.
# We craft a variety of plausible, null-terminated byte sequences representing:
# - file: URIs (absolute and relative)
# - plain filesystem paths (POSIX and Windows-like)
# - http/https URLs
# - data: URIs (small payloads)
# - file URIs with percent-encoding and spaces
# The fuzz stubs require non-empty buffers; libxml2 expects UTF-8.

_SCHEMES = [
    "http", "https", "file", "data"
]

_POSIX_DIRS = [
    "/tmp", "/var/tmp", "/usr/share", "/etc", "/home/user", "/", ".", ".."
]

_WIN_DRIVES = [
    "C:", "D:", "E:"
]

_HOSTS = [
    "localhost", "example.com", "127.0.0.1", "[::1]"
]

_PATH_SEGMENTS = [
    "", "docs", "xml", "xsl", "style", "include", "import", "images",
    "data", "test", "..", ".", "%20space", "unicodé", "こんにちは", "a" * 10
]

_QUERY_KEYS = ["q", "id", "param", "mode", "select", "name"]

_DATA_MIME = [
    "text/plain", "text/xml", "application/xml", "application/octet-stream"
]

_DEF_XML_SNIPPET = b"<root/>"


def _rand_bool(r: random.Random, p: float) -> bool:
    return r.random() < p


def _rand_choice(r: random.Random, arr: List[str]) -> str:
    return arr[r.randrange(len(arr))]


def _rand_path(r: random.Random) -> str:
    # Build a reasonable path with mixed segments
    segs = []
    n = r.randint(1, 4)
    for _ in range(n):
        seg = _rand_choice(r, _PATH_SEGMENTS)
        # ensure no empty consecutive slashes unless intended
        segs.append(seg)
    path = "/".join(segs)
    # occasionally ensure it ends with .xml or .xsl to trigger specific loaders
    if _rand_bool(r, 0.6):
        ext = _rand_choice(r, [".xml", ".xsl", ".xslt", ".txt"]) 
        # avoid double extension on segments that already look like files
        if not path.endswith(tuple([".xml", ".xsl", ".xslt", ".txt"])):
            if not path or path.endswith("/"):
                path += "file" + ext
            else:
                path += ext
    return path


def _build_http_url(r: random.Random) -> str:
    host = _rand_choice(r, _HOSTS)
    port = (":" + str(r.randint(1, 65535))) if _rand_bool(r, 0.2) else ""
    path = "/" + _rand_path(r).lstrip("/")
    # query
    if _rand_bool(r, 0.5):
        qparts = []
        for _ in range(r.randint(1, 3)):
            k = _rand_choice(r, _QUERY_KEYS)
            v = ''.join(r.choice(string.ascii_letters + string.digits + "-_.") for _ in range(r.randint(1, 6)))
            qparts.append(f"{k}={v}")
        query = "?" + "&".join(qparts)
    else:
        query = ""
    frag = ("#" + ''.join(r.choice(string.ascii_lowercase) for _ in range(r.randint(1, 6)))) if _rand_bool(r, 0.2) else ""
    scheme = _rand_choice(r, ["http", "https"]) 
    return f"{scheme}://{host}{port}{path}{query}{frag}"


def _build_file_uri(r: random.Random) -> str:
    # Either file:///absolute or file:relative
    if _rand_bool(r, 0.7):
        base = _rand_choice(r, _POSIX_DIRS)
        path = base.rstrip('/') + '/' + _rand_path(r).lstrip('/')
        # percent-encode space variant
        if _rand_bool(r, 0.3):
            path = path.replace(' ', '%20')
        return "file://" + path
    else:
        # file:relative/path.xsl
        rel = _rand_path(r)
        return "file:" + rel


def _build_posix_path(r: random.Random) -> str:
    base = _rand_choice(r, _POSIX_DIRS)
    return (base.rstrip('/') + '/' + _rand_path(r).lstrip('/')).replace('//', '/')


def _build_windows_path(r: random.Random) -> str:
    drive = _rand_choice(r, _WIN_DRIVES)
    segs = _rand_path(r).replace('/', '\\')
    return f"{drive}\\{segs}"


def _build_data_uri(r: random.Random) -> str:
    import base64
    mime = _rand_choice(r, _DATA_MIME)
    if mime.endswith('xml'):
        payload = _DEF_XML_SNIPPET
    else:
        # small ASCII payload
        payload = (''.join(r.choice(string.ascii_letters + string.digits + ' ') for _ in range(r.randint(4, 24)))).encode('utf-8')
    if _rand_bool(r, 0.6):
        b64 = base64.b64encode(payload).decode('ascii')
        return f"data:{mime};base64,{b64}"
    else:
        # URL-encoded (very small and simple)
        safe = ''.join((chr(c) if 32 <= c < 127 and chr(c) not in ' %' else '%{:02X}'.format(c)) for c in payload)
        return f"data:{mime},{safe}"


def _build_plain_relative(r: random.Random) -> str:
    # Relative paths used often by XSLT includes/imports
    choices = ["./" + _rand_path(r), "../" + _rand_path(r), _rand_path(r)]
    s = _rand_choice(r, choices)
    # sometimes include spaces that are not encoded, libxml2 typically handles
    if _rand_bool(r, 0.3):
        s = s.replace('%20', ' ')
    return s


def _pick_uri(r: random.Random) -> str:
    kind = r.random()
    if kind < 0.25:
        return _build_http_url(r)
    elif kind < 0.5:
        return _build_file_uri(r)
    elif kind < 0.65:
        return _build_data_uri(r)
    elif kind < 0.8:
        return _build_posix_path(r)
    elif kind < 0.9:
        return _build_windows_path(r)
    else:
        return _build_plain_relative(r)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a bundle of URIs and join with newlines so a single buffer can be reused
    # by multiple FUZZ_PARAM_STR calls if the harness reads sequentially.
    n = r.randint(1, 4)
    uris = []
    for _ in range(n):
        uri = _pick_uri(r)
        # Guarantee non-empty and reasonable length
        if not uri:
            uri = "file:/tmp/a.xml"
        if len(uri) > 1000:
            uri = uri[:1000]
        uris.append(uri)
    # Join with newlines; each consumer typically uses c_str(), NUL-terminated OK.
    payload = "\n".join(uris)
    # Ensure ASCII/UTF-8 bytes
    data = payload.encode('utf-8')
    # Cap size to 4096
    if len(data) > 4096:
        data = data[:4096]
    return data
